#!/usr/bin/env python3
"""One-shot environment diagnostics verifier for Diagram Design.

Runs read-only checks for local readiness and exits non-zero only on hard failures
(or warnings when --strict is supplied).
"""

from __future__ import annotations

import argparse
import json
import os
import platform
import shutil
import subprocess
import sys
from dataclasses import asdict, dataclass
from datetime import datetime, timezone
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
SKILL_RELATIVE = Path("skills/diagram-design/SKILL.md")

MAINTAINER_MARKERS = (
    Path("CONTRIBUTING.md"),
    Path(".github/workflows/ci.yml"),
    Path("scripts/verify-plugin-package.py"),
)

EXPECTED_SCRIPTS = (
    Path("scripts/verify-drawio-import.py"),
    Path("scripts/verify-mermaid-import.py"),
    Path("scripts/verify-excalidraw-import.py"),
    Path("scripts/verify-motion.py"),
    Path("scripts/lint-skin.py"),
    Path("scripts/verify-docs-sync.py"),
)

ROUTING_SURFACES = {
    Path("commands/export-diagram.md"): "references/export.md",
    Path("commands/import-drawio.md"): "references/import-drawio.md",
    Path("commands/import-mermaid.md"): "references/import-mermaid.md",
    Path("commands/import-excalidraw.md"): "references/import-excalidraw.md",
    Path("commands/profile.md"): "references/profiles.md",
    Path("commands/doctor.md"): "references/doctor.md",
    Path("prompts/export-diagram.md"): "references/export.md",
    Path("prompts/import-mermaid.md"): "references/import-mermaid.md",
    Path("prompts/import-excalidraw.md"): "references/import-excalidraw.md",
    Path("prompts/profile.md"): "references/profiles.md",
    Path("prompts/doctor.md"): "references/doctor.md",
}

VERSION_PROBE = "import sys; print('.'.join(str(p) for p in sys.version_info[:3]))"

PASS = "pass"
WARN = "warn"
FAIL = "fail"


@dataclass
class CheckResult:
    name: str
    status: str
    message: str
    fix: str | None = None


def run_command(command: list[str]) -> subprocess.CompletedProcess[str]:
    """Run a command, reporting a failure to launch the way a bad exit is reported.

    A name on PATH is not always a runnable program: an App Execution Alias for
    an uninstalled app, a dangling symlink, or a file without the exec bit raise
    instead of exiting. Every caller here only asks whether the command answered,
    so surface that as a non-zero result carrying the OS error rather than letting
    it unwind the whole doctor.
    """
    try:
        return subprocess.run(
            command,
            capture_output=True,
            text=True,
            encoding="utf-8",
            errors="replace",
            check=False,
        )
    except OSError as exc:
        return subprocess.CompletedProcess(command, 1, "", str(exc))


@dataclass
class PythonProbe:
    """What resolving an interpreter name actually turned up."""

    command: str | None = None
    executable: str | None = None
    version: str | None = None
    error: str | None = None


def probe_python_command() -> PythonProbe:
    """Resolve python3 first, then python, preferring a name that actually runs.

    Presence on PATH is not evidence of an interpreter. On Windows the
    ``python3`` App Execution Alias ships on PATH by default and exits
    non-zero with a Microsoft Store prompt, so a machine with a working
    ``python`` is otherwise reported as having no usable Python at all. Fall
    through to the next candidate when the preferred name cannot report its
    own version, and keep the first name found so a total failure still says
    what was tried.
    """
    fallback = PythonProbe()
    for candidate in ("python3", "python"):
        executable = shutil.which(candidate)
        if executable is None:
            continue
        probe = run_command([candidate, "-c", VERSION_PROBE])
        version = probe.stdout.strip()
        if probe.returncode == 0 and version:
            return PythonProbe(command=candidate, executable=executable, version=version)
        if fallback.command is None:
            fallback = PythonProbe(
                command=candidate,
                executable=executable,
                error=probe.stderr.strip() or "version probe failed",
            )
    return fallback


def check_python_runtime() -> tuple[CheckResult, str | None]:
    probe = probe_python_command()
    command_name, executable = probe.command, probe.executable
    if command_name is None or executable is None:
        return (
            CheckResult(
                name="Python runtime",
                status=FAIL,
                message="No python3 or python command was found on PATH.",
                fix="Install Python 3.10+ and ensure python3 or python is available on PATH.",
            ),
            None,
        )

    if probe.version is None:
        detail = probe.error or "version probe failed"
        return (
            CheckResult(
                name="Python runtime",
                status=FAIL,
                message=f"Could not query version via {command_name}: {detail}",
                fix="Ensure the selected Python command is executable and not blocked by shell aliases.",
            ),
            command_name,
        )

    version_text = probe.version
    try:
        major, minor, patch = (int(part) for part in version_text.split(".", 2))
    except ValueError:
        return (
            CheckResult(
                name="Python runtime",
                status=FAIL,
                message=f"Unexpected Python version format from {command_name}: {version_text!r}",
                fix="Use a standard CPython installation with semantic version output.",
            ),
            command_name,
        )

    if (major, minor) < (3, 10):
        return (
            CheckResult(
                name="Python runtime",
                status=FAIL,
                message=(
                    f"Python {major}.{minor}.{patch} found via {command_name} at {executable}; "
                    "Diagram Design requires Python >= 3.10."
                ),
                fix="Upgrade Python to 3.10+ and re-run /diagram-design:doctor.",
            ),
            command_name,
        )

    return (
        CheckResult(
            name="Python runtime",
            status=PASS,
            message=f"Python {major}.{minor}.{patch} found via {command_name} at {executable}.",
        ),
        command_name,
    )


def check_playwright(python_cmd: str | None) -> CheckResult:
    if python_cmd is None:
        return CheckResult(
            name="Playwright PNG export readiness",
            status=FAIL,
            message="Playwright check skipped because no Python command was available.",
            fix="Provision an approved Playwright renderer after resolving Python, then re-run this check.",
        )

    import_probe = run_command([python_cmd, "-c", "import playwright"])
    if import_probe.returncode != 0:
        return CheckResult(
            name="Playwright PNG export readiness",
            status=WARN,
            message="Playwright package is not available in the active Python interpreter.",
            fix="Provision an approved Playwright renderer in the host environment, then re-run this check.",
        )

    chromium_probe = run_command(
        [
            python_cmd,
            "-c",
            (
                "from pathlib import Path\n"
                "from playwright.sync_api import sync_playwright\n"
                "with sync_playwright() as p:\n"
                "    path = Path(p.chromium.executable_path)\n"
                "    print(path)\n"
                "    raise SystemExit(0 if path.is_file() else 3)\n"
            ),
        ]
    )
    if chromium_probe.returncode == 0:
        return CheckResult(
            name="Playwright PNG export readiness",
            status=PASS,
            message=f"Playwright is installed and Chromium is present at {chromium_probe.stdout.strip()}.",
        )

    detail = chromium_probe.stderr.strip() or "Chromium executable was not detected"
    return CheckResult(
        name="Playwright PNG export readiness",
        status=WARN,
        message=f"Playwright is installed but Chromium is not ready: {detail}",
        fix="Provision an approved browser for the existing Playwright installation, then re-run this check.",
    )


def is_maintainer_checkout(root: Path) -> bool:
    """Return whether root is a source checkout with maintainer-only surfaces."""
    return all((root / marker).is_file() for marker in MAINTAINER_MARKERS)


def resolve_skill_file(root: Path) -> Path | None:
    """Find SKILL.md in either a repository/plugin root or standalone skill root."""
    repository_skill = root / SKILL_RELATIVE
    if repository_skill.is_file():
        return repository_skill
    standalone_skill = root / "SKILL.md"
    if standalone_skill.is_file():
        return standalone_skill
    return None


def check_expected_scripts(root: Path) -> CheckResult:
    if not is_maintainer_checkout(root):
        return CheckResult(
            name="Expected script presence",
            status=PASS,
            message="Installed-skill mode detected; maintainer-only repository scripts are not required.",
        )

    missing = [path.as_posix() for path in EXPECTED_SCRIPTS if not (root / path).is_file()]
    if missing:
        return CheckResult(
            name="Expected script presence",
            status=FAIL,
            message="Missing required script(s): " + ", ".join(missing),
            fix="Restore missing scripts from the repository root and re-run diagnostics.",
        )
    return CheckResult(
        name="Expected script presence",
        status=PASS,
        message=f"All required scripts are present ({len(EXPECTED_SCRIPTS)} checked).",
    )


def check_routing_surfaces(root: Path) -> CheckResult:
    if not is_maintainer_checkout(root):
        return CheckResult(
            name="Plugin wiring surfaces",
            status=PASS,
            message="Installed-skill mode detected; maintainer command/prompt wiring is not required.",
        )

    missing_files: list[str] = []
    mismatched: list[str] = []

    for relative_path, reference in ROUTING_SURFACES.items():
        path = root / relative_path
        if not path.is_file():
            missing_files.append(relative_path.as_posix())
            continue
        source = path.read_text(encoding="utf-8")
        if reference not in source:
            mismatched.append(f"{relative_path.as_posix()} -> {reference}")

    if missing_files or mismatched:
        issues: list[str] = []
        if missing_files:
            issues.append("missing files: " + ", ".join(missing_files))
        if mismatched:
            issues.append("reference mismatches: " + ", ".join(mismatched))
        return CheckResult(
            name="Plugin wiring surfaces",
            status=FAIL,
            message="; ".join(issues),
            fix="Ensure each command/prompt file exists and routes to the matching references/*.md file.",
        )

    return CheckResult(
        name="Plugin wiring surfaces",
        status=PASS,
        message=f"All command/prompt routing surfaces are present and wired ({len(ROUTING_SURFACES)} checked).",
    )


def check_common_path_mistakes(root: Path, cwd: Path) -> CheckResult:
    warnings: list[str] = []
    fixes: list[str] = []

    if resolve_skill_file(root) is None:
        warnings.append(
            "Diagram Design SKILL.md was not found under the resolved installation root."
        )
        fixes.append("Reinstall or update Diagram Design, then run the doctor again.")

    if platform.system().lower().startswith("win") and " " in str(cwd):
        warnings.append(
            "Path contains spaces on Windows; unquoted shell examples can fail for import/export commands."
        )
        fixes.append('Use quoted paths, e.g. "C:/path with spaces/diagram.html".')

    if not warnings:
        return CheckResult(
            name="Common path mistakes",
            status=PASS,
            message="No common path mistakes were detected.",
        )

    return CheckResult(
        name="Common path mistakes",
        status=WARN,
        message=" ".join(warnings),
        fix=" ".join(fixes),
    )


def summarize(checks: list[CheckResult], strict: bool) -> tuple[str, dict[str, int], int]:
    counts = {PASS: 0, WARN: 0, FAIL: 0}
    for check in checks:
        counts[check.status] += 1

    if counts[FAIL] > 0:
        status = "FAIL"
    elif counts[WARN] > 0:
        status = "WARN"
    else:
        status = "PASS"

    exit_code = 0
    if counts[FAIL] > 0:
        exit_code = 1
    elif strict and counts[WARN] > 0:
        exit_code = 1

    return status, counts, exit_code


def print_report(checks: list[CheckResult], strict: bool, emit_json: bool) -> int:
    status, counts, exit_code = summarize(checks, strict)
    print(
        f"Doctor summary: {status} ({counts[PASS]} pass, {counts[WARN]} warn, {counts[FAIL]} fail)"
    )

    markers = {PASS: "PASS", WARN: "WARN", FAIL: "FAIL"}
    for check in checks:
        print(f"[{markers[check.status]}] {check.name}: {check.message}")

    needs_next_actions = counts[WARN] > 0 or counts[FAIL] > 0
    if needs_next_actions:
        print("\nNext actions")
        for check in checks:
            if check.status in (WARN, FAIL) and check.fix:
                print(f"- {check.fix}")

    if emit_json:
        payload = {
            "status": status,
            "counts": counts,
            "checks": [asdict(check) for check in checks],
            "timestamp": datetime.now(timezone.utc).isoformat(),
            "strict": strict,
            "platform": {
                "system": platform.system(),
                "release": platform.release(),
                "python": sys.version.split()[0],
                "cwd": str(Path.cwd()),
                "root": str(ROOT),
            },
        }
        print(json.dumps(payload, indent=2))

    return exit_code


def run_doctor(root: Path, cwd: Path, strict: bool, emit_json: bool) -> int:
    checks: list[CheckResult] = []

    python_check, python_cmd = check_python_runtime()
    checks.append(python_check)
    checks.append(check_playwright(python_cmd))
    checks.append(check_expected_scripts(root))
    checks.append(check_routing_surfaces(root))
    checks.append(check_common_path_mistakes(root, cwd))

    return print_report(checks, strict, emit_json)


def parse_args(argv: list[str]) -> argparse.Namespace:
    parser = argparse.ArgumentParser(
        description="Run one-shot Diagram Design environment diagnostics."
    )
    parser.add_argument(
        "--strict",
        action="store_true",
        help="Treat warnings as failures.",
    )
    parser.add_argument(
        "--json",
        action="store_true",
        help="Emit machine-readable JSON report after the human summary.",
    )
    return parser.parse_args(argv)


def main(argv: list[str] | None = None) -> int:
    args = parse_args(sys.argv[1:] if argv is None else argv)
    root = ROOT
    cwd = Path.cwd()
    return run_doctor(root, cwd, args.strict, args.json)


if __name__ == "__main__":
    raise SystemExit(main())

scripts/verify-excalidraw-import.py.text:
#!/usr/bin/env python3
"""Structural and adversarial verification for Excalidraw import.

The driver invokes the shipped extractor as a subprocess, imports its public
module surface for resource-limit checks, and verifies the documentation and
command wiring. Exit 0 only when every gate passes.
"""

from __future__ import annotations

import contextlib
import importlib.util
import io
import json
import os
import re
import subprocess
import sys
import tempfile
from pathlib import Path

sys.dont_write_bytecode = True

ROOT = Path(__file__).resolve().parent.parent
SKILL = ROOT / "skills/diagram-design/SKILL.md"
EXTRACT = ROOT / "skills/diagram-design/scripts/excalidraw_extract.py"
IMPORT_REF = ROOT / "skills/diagram-design/references/import-excalidraw.md"
COMMAND = ROOT / "commands/import-excalidraw.md"
PROMPT = ROOT / "prompts/import-excalidraw.md"
WHITEBOARD = ROOT / "scripts/fixtures/sample-whiteboard.excalidraw"
ADVERSARIAL = ROOT / "scripts/fixtures/sample-adversarial.excalidraw"
EXAMPLE = ROOT / "skills/diagram-design/assets/example-import-excalidraw.html"


def fail(message: str) -> None:
    print(f"FAIL: {message}", file=sys.stderr)
    raise SystemExit(1)


def ok(message: str) -> None:
    print(f"OK: {message}")


def normalize_newlines(text: str) -> str:
    return text.replace("\r\n", "\n").replace("\r", "\n")


def invoke(args: list[str]) -> subprocess.CompletedProcess[str]:
    return subprocess.run(
        [sys.executable, str(EXTRACT), *args],
        capture_output=True,
        text=True,
        encoding="utf-8",
        errors="replace",
    )


def run_extract(args: list[str]) -> str:
    process = invoke(args)
    if process.returncode != 0:
        fail(
            f"extractor exited {process.returncode} for {args}: "
            f"{process.stderr.strip()}"
        )
    return process.stdout


def expect_error(args: list[str], message: str) -> None:
    process = invoke(args)
    if process.returncode != 2 or message not in process.stderr:
        fail(
            f"expected exit 2 containing {message!r} for {args}; got "
            f"{process.returncode}: {process.stderr.strip()!r}"
        )


def load_extractor_module():
    spec = importlib.util.spec_from_file_location(
        "diagram_design_excalidraw_extract", EXTRACT
    )
    if spec is None or spec.loader is None:
        fail("could not load Excalidraw extractor module")
    module = importlib.util.module_from_spec(spec)
    sys.modules[spec.name] = module
    spec.loader.exec_module(module)
    return module


def scene(name: str, elements: list[dict], files: dict | None = None) -> str:
    return json.dumps(
        {
            "type": "excalidraw",
            "version": 2,
            "source": name,
            "elements": elements,
            "appState": {},
            "files": files or {},
        }
    )


def check_files() -> None:
    for path in (
        SKILL,
        EXTRACT,
        IMPORT_REF,
        COMMAND,
        PROMPT,
        WHITEBOARD,
        ADVERSARIAL,
        EXAMPLE,
    ):
        if not path.is_file():
            fail(f"missing {path.relative_to(ROOT)}")
    ok("all Excalidraw import artifacts present")


def check_whiteboard() -> None:
    payload = json.loads(run_extract([str(WHITEBOARD), "--json"]))["scene"]
    analysis = payload["analysis"]
    nodes = {node["id"]: node for node in payload["nodes"]}
    edges = payload["edges"]

    if analysis["nodes_total"] != 10 or analysis["edges_total"] != 6:
        fail(
            "fixture graph mis-parsed: "
            f"{analysis['nodes_total']}n/{analysis['edges_total']}e"
        )
    if analysis["containers"] != 2 or analysis["max_depth"] != 1:
        fail("frames were not parsed as containers with depth-1 members")
    if nodes["valid-record"]["shape"] != "rhombus":
        fail("diamond was not classified as rhombus")
    if nodes["csv-import"]["shape"] != "ellipse":
        fail("ellipse shape was not retained")
    if nodes["web-form"]["label"] != "Web Form":
        fail("bound text was not folded into its container node")
    if nodes["valid-record"]["label"] != "Valid\nrecord?":
        fail("multiline bound text was not retained")
    if nodes["intake-api"]["parent"] != "frame-pipeline":
        fail("frameId membership was not resolved")
    if not any(edge["label"] == "submit" for edge in edges):
        fail("arrow-bound text was not folded into the edge label")
    dashed_no = next(edge for edge in edges if edge["label"] == "no — fix")
    if not dashed_no["dashed"]:
        fail("dashed strokeStyle was not retained on the loop-back edge")
    if not analysis["has_cycle"]:
        fail("validate loop did not feed cycle detection")
    if analysis["edges_dangling"] != 0:
        fail("bound fixture edges were reported dangling")
    if not analysis["hubs"] or analysis["hubs"][0]["id"] != "intake-api":
        fail("hub ranking did not surface the intake API")
    if "Old flow — ignore" not in analysis["orphans"]:
        fail("unconnected sticky text was not reported")
    if analysis["type_candidates"][0] != "flowchart":
        fail("diamond did not rank flowchart first among type candidates")
    group_entries = [
        group for group in analysis["collapsible_groups"] if group["id"] == "group-crm"
    ]
    if not group_entries or group_entries[0]["children"] != 2:
        fail("explicit group was not offered as a collapsible cluster")
    if not any(
        group["id"] == "frame-pipeline" and group["children"] == 4
        for group in analysis["collapsible_groups"]
    ):
        fail("frame members were not offered as a collapsible group")
    discarded = payload["discarded"]
    if (
        discarded["freedraw_strokes"] != 1
        or discarded["image_payloads"] != 1
        or discarded["links"] != 1
        or discarded["deleted_elements"] != 1
    ):
        fail(f"fidelity-ledger discard counts wrong: {discarded}")

    digest = run_extract([str(WHITEBOARD), "--max-rows", "3"])
    for needle in (
        "source canvas:",
        "type candidates: flowchart",
        "budget:",
        "- discarded:",
        "### Nodes",
        "### Edges",
        "+",
    ):
        if needle not in digest:
            fail(f"whiteboard digest missing {needle!r}")
    ok("whiteboard parses: shapes, frames, bound labels, groups, cycle, ledger")


def check_bindings_and_shapes(tmp: Path) -> None:
    board = tmp / "bindings.excalidraw"
    board.write_text(
        scene(
            "bindings",
            [
                {"id": "a", "type": "rectangle", "x": 0, "y": 0, "width": 100, "height": 60},
                {"id": "b", "type": "rectangle", "x": 300, "y": 0, "width": 100, "height": 60},
                {
                    "id": "both",
                    "type": "arrow",
                    "x": 100,
                    "y": 30,
                    "points": [[0, 0], [200, 0]],
                    "startArrowhead": "arrow",
                    "endArrowhead": "arrow",
                    "startBinding": {"elementId": "a", "focus": 0, "gap": 4},
                    "endBinding": {"elementId": "b", "focus": 0, "gap": 4},
                },
                {
                    "id": "plain-line",
                    "type": "line",
                    "x": 100,
                    "y": 90,
                    "points": [[0, 0], [100, 20], [200, 0]],
                    "startBinding": {"elementId": "a", "focus": 0, "gap": 4},
                    "endBinding": {"elementId": "b", "focus": 0, "gap": 4},
                },
                {
                    "id": "loose",
                    "type": "arrow",
                    "x": 0,
                    "y": 200,
                    "points": [[0, 0], [50, 50]],
                    "startBinding": None,
                    "endBinding": None,
                },
                {
                    "id": "stale",
                    "type": "arrow",
                    "x": 0,
                    "y": 300,
                    "points": [[0, 0], [50, 50]],
                    "startBinding": {"elementId": "deleted-node", "focus": 0, "gap": 4},
                    "endBinding": {"elementId": "b", "focus": 0, "gap": 4},
                },
                {"id": "widget", "type": "hyperwidget", "x": 0, "y": 400, "width": 10, "height": 10},
            ],
        ),
        encoding="utf-8",
    )
    payload = json.loads(run_extract([str(board), "--json"]))["scene"]
    edges = {edge["id"]: edge for edge in payload["edges"]}
    if not edges["both"]["bidirectional"]:
        fail("double-arrowhead arrow was not retained as bidirectional")
    if not edges["plain-line"]["undirected"]:
        fail("line without arrowheads was not retained as undirected")
    if edges["plain-line"]["waypoints"] != 1:
        fail("intermediate line points were not counted as waypoints")
    if edges["loose"]["source"] is not None or edges["loose"]["target"] is not None:
        fail("unbound arrow endpoints were not reported dangling")
    if edges["stale"]["source"] is not None:
        fail("binding to a missing element was not reported dangling")
    if payload["analysis"]["edges_dangling"] != 2:
        fail("dangling edge count wrong")
    if payload["discarded"]["unknown_elements"] != 1:
        fail("unknown element type was not counted")
    ok("bindings, arrowheads, waypoints, dangling edges, unknown elements")


def check_arrow_directions(tmp: Path) -> None:
    cases = (
        ("start-only", "arrow", None, "b", "a", False, False, ["b"], ["a"]),
        ("end-only", None, "arrow", "a", "b", False, False, ["a"], ["b"]),
        ("both", "arrow", "arrow", "a", "b", True, False, [], []),
        ("neither", None, None, "a", "b", False, True, [], []),
    )
    for name, start_head, end_head, source, target, bidir, undirected, entries, terminals in cases:
        board = tmp / f"arrow-{name}.excalidraw"
        board.write_text(
            scene(
                name,
                [
                    {"id": "a", "type": "rectangle", "x": 0, "y": 0, "width": 10, "height": 10},
                    {"id": "b", "type": "rectangle", "x": 20, "y": 0, "width": 10, "height": 10},
                    {
                        "id": "edge",
                        "type": "arrow",
                        "startArrowhead": start_head,
                        "endArrowhead": end_head,
                        "startBinding": {"elementId": "a"},
                        "endBinding": {"elementId": "b"},
                    },
                ],
            ),
            encoding="utf-8",
        )
        payload = json.loads(run_extract([str(board), "--json"]))["scene"]
        edge = payload["edges"][0]
        if (edge["source"], edge["target"]) != (source, target):
            fail(f"{name} arrow direction was {edge['source']} -> {edge['target']}")
        if edge["bidirectional"] is not bidir or edge["undirected"] is not undirected:
            fail(f"{name} arrow flags were not retained")
        analysis = payload["analysis"]
        if analysis["entry_points"] != entries or analysis["terminals"] != terminals:
            fail(f"{name} arrow produced incorrect entry/terminal analysis")
        if analysis["has_cycle"] is not bidir:
            fail(f"{name} arrow produced incorrect cycle analysis")
    ok("start-only, end-only, bidirectional, and undirected arrows keep their semantics")


def check_bidirectional_cycle(tmp: Path) -> None:
    board = tmp / "bidirectional-cycle.excalidraw"
    board.write_text(
        scene(
            "bidirectional-cycle",
            [
                {"id": node_id, "type": "rectangle"}
                for node_id in ("root", "a", "b")
            ]
            + [
                {
                    "id": "entry",
                    "type": "arrow",
                    "startBinding": {"elementId": "root"},
                    "endBinding": {"elementId": "a"},
                },
                {
                    "id": "cycle",
                    "type": "arrow",
                    "startArrowhead": "arrow",
                    "endArrowhead": "arrow",
                    "startBinding": {"elementId": "a"},
                    "endBinding": {"elementId": "b"},
                },
            ],
        ),
        encoding="utf-8",
    )
    analysis = json.loads(run_extract([str(board), "--json"]))["scene"]["analysis"]
    if not analysis["has_cycle"] or "tree" in analysis["type_candidates"]:
